@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap');
:root{--ink:#20303b;--muted:#8a959b;--paper:#fbfaf7;--line:#eeeae2;--coral:#e8957c;--coral-dark:#bf6f5b;--teal:#5f9895;--navy:#203847;--gold:#ddbd78;--soft:#f4f1ea;--shadow:0 12px 35px rgba(34,49,56,.09)}
*{box-sizing:border-box}body{margin:0;background:#f8f6f1;color:var(--ink);font-family:'DM Sans',sans-serif;font-size:13px}button{font:inherit;color:inherit;cursor:pointer}button:focus-visible{outline:2px solid #e8957c;outline-offset:3px}.app-shell{min-height:100vh;max-width:1760px;margin:auto;padding:0 30px 24px}.topbar{height:81px;border-bottom:1px solid #eae6de;display:flex;align-items:center;justify-content:space-between}.brand{border:0;background:none;display:flex;align-items:center;gap:11px;padding:0;text-align:left}.brand-mark{width:37px;height:37px;border-radius:12px;background:#203847;color:#f6d79d;display:grid;place-items:center;font-size:22px;box-shadow:0 5px 12px #20384730}.brand-words{display:grid;gap:3px}.brand-words b{font:700 17px 'Playfair Display',serif;letter-spacing:.3px}.brand-words small{font-size:8px;letter-spacing:1.55px;color:#8b969a}.season-tag{margin-left:90px;display:flex;gap:8px;align-items:center;color:#6b7478;font-size:9px;font-weight:700;letter-spacing:1.8px}.sun-icon{font-size:18px;color:#dfa85f}.top-right{display:flex;align-items:center;gap:12px}.day-chip{height:32px;padding:0 12px;border:1px solid #e7e2d9;border-radius:20px;display:flex;align-items:center;gap:7px;color:#536269;font-size:9px;font-weight:700;letter-spacing:1px}.calendar-icon{font-size:15px;color:#b78461}.icon-button,.avatar-mini{border:0;width:33px;height:33px;border-radius:50%;background:#f0ede6;color:#627078;font-size:16px}.avatar-mini{background:#e8cbb8;color:#654837;font-weight:700;font-size:12px}
.game-layout{display:grid;grid-template-columns:224px minmax(420px,1fr) 230px;gap:23px;padding-top:22px}.left-rail,.right-rail{min-width:0}.rail-heading,.right-heading{height:27px;display:flex;justify-content:space-between;align-items:center;color:#889296;font-size:9px;font-weight:700;letter-spacing:1.45px}.tiny-spark,.pin-icon,.note-icon{color:#d39d67;font-size:17px}.player-card{display:flex;align-items:center;gap:10px;padding:15px 0 17px;border-bottom:1px solid var(--line);position:relative}.player-avatar{width:41px;height:41px;border-radius:50%;background:linear-gradient(145deg,#edc8a9,#b57864);display:grid;place-items:center;color:white;font:700 17px 'Playfair Display',serif;position:relative;border:3px solid white;box-shadow:0 2px 6px #20303b12}.player-avatar i{font-style:normal;position:absolute;right:-3px;bottom:-4px;color:#d9aa67;font-size:12px}.player-card>div:nth-child(2){display:grid;gap:4px}.player-card b{font-size:11px}.player-card small{font-size:9px;color:#92999b}.edit-name{border:0;background:none;color:#aab0af;margin-left:auto;font-size:14px}.energy-wrap{padding:18px 0 20px;border-bottom:1px solid var(--line)}.energy-heading{display:flex;justify-content:space-between;font-size:9px;letter-spacing:1.2px;color:#899395;font-weight:700}.energy-heading b{color:#58676d;letter-spacing:0;font-size:10px}.energy-track{display:flex;gap:6px;margin-top:10px}.energy-orb{height:6px;flex:1;background:#e8e5de;border-radius:5px;transition:background .3s}.energy-orb.active{background:linear-gradient(90deg,#e7a585,#e5bd7c)}.energy-note{display:block;color:#a0a5a3;font-size:9px;margin-top:9px}.location-heading{margin-top:17px}.location-list{display:grid;gap:3px;margin-top:4px}.location-button{border:0;background:none;border-radius:7px;width:100%;height:39px;display:flex;align-items:center;gap:10px;text-align:left;padding:0 10px;color:#6d7a80;transition:.18s}.location-button:hover{background:#f1eee8}.location-button.active{background:#e8efeb;color:#375f5e}.location-button .loc-icon{font-size:16px;width:17px;text-align:center}.location-button b{font-size:10px;letter-spacing:.3px;font-weight:600}.location-button .loc-time{margin-left:auto;font-size:8px;color:#a1aaa9}.festival-card{margin-top:20px;background:#eef0e8;border-radius:9px;padding:12px 12px 10px;display:grid;grid-template-columns:28px 1fr;column-gap:7px;align-items:center;position:relative;overflow:hidden}.festival-sun{font-size:23px;color:#d9a85d;grid-row:span 2}.festival-card>div:nth-child(2){display:grid;gap:4px}.festival-card b{font-size:8px;letter-spacing:.8px}.festival-card small{font-size:8px;color:#89928b}.festival-progress{grid-column:1 / -1;height:4px;background:#d9ddd3;border-radius:4px;margin-top:11px;overflow:hidden}.festival-progress span{display:block;width:0;height:100%;background:#cf9d63;border-radius:4px;transition:width .4s}.festival-caption{grid-column:1 / -1;margin-top:7px!important}.journal-link{border:0;background:none;padding:17px 3px;color:#758087;font-size:10px;display:flex;align-items:center;gap:8px;width:100%;text-align:left}.journal-link>span{font-size:15px;color:#c4876a}.journal-link kbd{margin-left:auto}
.stage-column{min-width:0}.scene-card{height:min(746px,calc(100vh - 125px));min-height:595px;position:relative;border-radius:11px;overflow:hidden;background:#d5cdbb;box-shadow:var(--shadow)}.scene-art,.scene-vignette{position:absolute;inset:0}.scene-art{overflow:hidden;background:linear-gradient(180deg,#99c2c7 0%,#d7cba8 52%,#61817d 53%,#456e70 100%);transition:filter .6s}.scene-art svg{width:100%;height:100%;display:block}.scene-vignette{background:linear-gradient(180deg,rgba(23,44,55,.31) 0%,transparent 23%,transparent 52%,rgba(21,37,43,.22) 70%,rgba(21,37,43,.53) 100%);pointer-events:none}.scene-topline{position:absolute;top:20px;left:22px;right:22px;display:flex;justify-content:space-between;align-items:center}.location-pill,.weather-pill{height:28px;border-radius:18px;padding:0 11px;background:#fcfbf2e8;display:flex;align-items:center;gap:7px;color:#55646a;font-size:8px;letter-spacing:1.2px;font-weight:700;box-shadow:0 3px 10px #34494c20}.location-dot{width:6px;height:6px;background:#de9a74;border-radius:50%}.weather-pill{font-weight:600;letter-spacing:.3px}.scene-caption{position:absolute;top:64px;left:25px;display:flex;gap:9px;color:#fff;text-shadow:0 1px 5px #1c3947a8;font-size:9px;letter-spacing:1px;font-weight:600}.caption-divider{opacity:.6}.scene-people{position:absolute;inset:0;pointer-events:none;display:flex;justify-content:center;align-items:flex-end;gap:2%;padding:0 11% 22%;transition:opacity .3s}.character-figure{height:min(41%,315px);max-width:32%;min-width:120px;filter:drop-shadow(0 10px 12px #142c3740);transform-origin:bottom;animation:arrive .65s cubic-bezier(.15,.8,.25,1) both}.character-figure svg{height:100%;width:auto;overflow:visible}.character-figure:nth-child(2){animation-delay:.1s}.character-figure:nth-child(3){animation-delay:.18s}@keyframes arrive{from{transform:translateY(25px);opacity:0}to{transform:translateY(0);opacity:1}}.scene-hint{position:absolute;right:22px;top:73px;color:#fff9;font-size:9px;text-shadow:0 1px 4px #20303b;letter-spacing:.4px}.scene-action{position:absolute;right:22px;bottom:250px;padding:8px 11px;border:1px solid #fff9;border-radius:20px;background:#20384755;color:white;display:flex;gap:7px;align-items:center;font-size:8px;letter-spacing:.8px;backdrop-filter:blur(4px)}.scene-action span{color:#f5d399}.dialogue-card{position:absolute;left:5%;right:5%;bottom:20px;min-height:194px;border:1px solid #fff9;background:rgba(252,250,245,.97);border-radius:8px;padding:14px 18px 10px;box-shadow:0 12px 32px #1f303746;backdrop-filter:blur(9px)}.dialogue-top{display:flex;align-items:center;gap:9px}.speaker-icon{width:29px;height:29px;border-radius:50%;background:#e8d3b6;color:#956d46;display:grid;place-items:center;font-size:14px}.speaker-meta{display:grid;gap:3px}.speaker-meta b{font-size:9px;letter-spacing:1.1px}.speaker-meta small{color:#9ba2a1;font-size:8px}.dialogue-mark{margin-left:auto;color:#dfcbb2;font:26px 'Playfair Display',serif}.dialogue-text{margin:10px 0 10px;color:#536067;font:600 14px/1.5 'Playfair Display',serif;max-width:780px}.choice-list{display:grid;grid-template-columns:1fr 1fr;gap:6px}.choice-button{min-height:34px;background:#fff;border:1px solid #eeeae2;border-radius:5px;text-align:left;padding:7px 10px;color:#5e6a70;font-size:10px;transition:.16s;display:flex;align-items:center;gap:8px}.choice-button:hover{border-color:#d6a17b;background:#fffaf4;transform:translateY(-1px)}.choice-number{width:18px;height:18px;border-radius:50%;background:#f1eee8;color:#aa8060;display:grid;place-items:center;font-size:8px;flex:none}.dialogue-footer{border-top:1px solid #efebe4;margin-top:11px;padding-top:8px;display:flex;justify-content:space-between;align-items:center}.dialogue-footer>span{font-size:8px;color:#a4a9a7;letter-spacing:.2px}.continue-button{border:0;background:none;color:#b87b61;font-size:8px;letter-spacing:1px;font-weight:700;padding:3px 0}.continue-button span{font-size:14px;margin-left:6px}.bottom-bar{height:40px;display:flex;justify-content:space-between;align-items:center;padding:0 3px}.quote{display:flex;align-items:center;gap:8px;color:#8c9898;font-size:10px}.quote span{color:#d3a66f;font-size:15px}.controls-legend{color:#a1a7a5;font-size:7px;letter-spacing:1px}.controls-legend kbd,.journal-link kbd{font-family:inherit;font-size:8px;border:1px solid #e5e1d9;border-radius:3px;padding:2px 4px;color:#899395}.controls-legend span{margin:0 5px}
.right-heading{height:27px}.help-dot{border:1px solid #dedbd4;background:none;color:#9da4a2;width:16px;height:16px;border-radius:50%;font-size:9px}.people-list{display:grid;gap:7px;margin-top:8px}.person-card{border:1px solid #ece8e1;background:#fcfbf8;border-radius:7px;padding:9px;display:grid;grid-template-columns:42px 1fr 16px;gap:9px;align-items:center;cursor:pointer;transition:.18s}.person-card:hover{border-color:#d7b99b;transform:translateY(-1px)}.person-portrait{height:43px;width:42px;border-radius:5px;overflow:hidden;background:#e9e3da}.person-portrait svg{width:100%;height:100%}.person-info{min-width:0}.person-info b{display:block;font-size:10px}.person-info small{display:block;color:#959d9c;font-size:8px;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.heart-meter{height:3px;background:#ece9e2;border-radius:3px;margin-top:7px;overflow:hidden}.heart-meter span{display:block;height:100%;width:0;background:#e29a84;transition:width .35s}.person-chevron{font-size:15px;color:#c4bcb0}.rail-divider{border-top:1px solid var(--line);margin:19px 0 12px}.town-heading{height:23px}.town-note{margin-top:8px;background:#f1eee7;border-radius:7px;padding:11px 12px;position:relative}.note-doodle{position:absolute;right:11px;top:4px;color:#d3a56e;font:25px 'Playfair Display',serif}.town-note p{font:12px/1.55 'Playfair Display',serif;color:#687378;margin:0 12px 9px 0}.town-note small{font-size:7px;letter-spacing:1px;color:#9ba19c}.memory-card{margin-top:12px;padding:10px;border:1px solid #eee9e1;border-radius:7px;display:grid;grid-template-columns:28px 1fr 20px;align-items:center;gap:7px}.memory-icon{width:26px;height:26px;border-radius:50%;background:#f6ead4;color:#c99a61;display:grid;place-items:center;font-size:15px}.memory-card b{font-size:9px;display:block}.memory-card small{font-size:8px;color:#9ba19c;display:block;margin-top:3px}.memory-card button{border:0;background:none;color:#b98365;font-size:14px}.save-status{margin-top:19px;color:#a5aaa7;font-size:7px;letter-spacing:1.1px;display:flex;align-items:center;gap:6px}.status-dot{width:5px;height:5px;background:#85ad8f;border-radius:50%}.status-dot.unsaved{background:#d9a15f}.toast{position:fixed;left:50%;bottom:24px;transform:translate(-50%,20px);padding:11px 18px;background:#203847;color:#fff;border-radius:24px;font-size:11px;box-shadow:0 8px 22px #1a303644;opacity:0;pointer-events:none;transition:.25s;z-index:20}.toast.show{transform:translate(-50%,0);opacity:1}.modal-backdrop{position:fixed;inset:0;background:#172b36a3;display:grid;place-items:center;padding:18px;z-index:30;backdrop-filter:blur(5px)}.modal-backdrop[hidden]{display:none}.modal-card{position:relative;background:#fcfbf8;border-radius:12px;width:min(560px,100%);max-height:min(80vh,700px);overflow:auto;padding:32px 36px 30px;box-shadow:0 20px 70px #112c3c4d}.modal-close{position:absolute;right:17px;top:13px;border:0;background:#f0ede7;border-radius:50%;width:29px;height:29px;font-size:19px;color:#718087}.modal-eyebrow{font-size:8px;letter-spacing:1.6px;color:#c48968;font-weight:700}.modal-card h2{font:600 29px 'Playfair Display',serif;margin:7px 0 19px}.modal-content{color:#627078;font-size:12px;line-height:1.7}.journal-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.journal-stat{background:#f3f0e9;padding:12px;border-radius:7px}.journal-stat b{display:block;color:#34464e;font-size:17px;font-family:'Playfair Display',serif}.journal-stat small{font-size:8px;letter-spacing:.8px;color:#919b98}.journal-entry{border-left:2px solid #e6bd8b;padding:2px 0 3px 12px;margin:12px 0}.journal-entry b{font-size:10px;color:#41525a}.journal-entry p{margin:3px 0;font:12px/1.5 'Playfair Display',serif}.journal-empty{padding:19px;text-align:center;background:#f4f1eb;border-radius:8px}.memory-grid{display:grid;gap:9px}.memory-item{padding:12px;background:#f4f1eb;border-radius:7px}.memory-item b{font:600 15px 'Playfair Display',serif;color:#42535a}.memory-item p{margin:4px 0 0}.modal-actions{display:flex;gap:8px;margin-top:17px}.modal-actions button{border:1px solid #e8e3db;background:#fff;border-radius:5px;padding:9px 12px;font-size:10px}.modal-actions .primary{background:#203847;color:white;border-color:#203847}
@media(max-width:1100px){.app-shell{padding:0 18px 18px}.game-layout{grid-template-columns:190px minmax(370px,1fr);gap:17px}.right-rail{grid-column:1 / -1;display:grid;grid-template-columns:190px 1fr 1fr 1fr;gap:12px;align-items:start;border-top:1px solid var(--line);padding-top:10px}.right-heading{grid-column:1}.people-list{grid-column:1;grid-row:2 / span 3}.rail-divider{display:none}.town-heading{grid-column:2;grid-row:1}.town-note{grid-column:2;grid-row:2}.memory-card{grid-column:3;grid-row:2;margin:0}.save-status{grid-column:4;grid-row:2}.scene-card{height:650px}.festival-card{margin-top:12px}}
@media(max-width:700px){body{font-size:12px}.app-shell{padding:0 11px max(12px,env(safe-area-inset-bottom))}.topbar{height:64px}.brand-mark{width:32px;height:32px}.brand-words b{font-size:15px}.brand-words small{font-size:6px}.season-tag{display:none}.top-right{gap:6px}.day-chip{height:28px;padding:0 8px;font-size:8px}.icon-button,.avatar-mini{width:29px;height:29px}.game-layout{display:flex;flex-direction:column;gap:12px;padding-top:10px}.left-rail{order:2;display:grid;grid-template-columns:1fr 1.15fr;column-gap:12px;align-items:start}.left-rail>.rail-heading:first-child,.player-card,.energy-wrap{display:none}.location-heading{grid-column:1 / -1;margin:0;height:24px}.location-list{grid-column:1 / -1;display:flex;overflow-x:auto;gap:5px;margin:2px 0 8px;padding-bottom:3px;scrollbar-width:none}.location-button{min-width:max-content;width:auto;padding:0 9px;height:33px;background:#f0eee8}.location-button.active{background:#e5eee9}.location-button .loc-time{display:none}.festival-card{margin:0;grid-column:1}.journal-link{grid-column:2;align-self:center;justify-content:center;padding:10px}.journal-link kbd{display:none}.stage-column{order:1}.scene-card{height:min(690px,calc(100dvh - 86px));min-height:570px;border-radius:8px}.scene-topline{top:12px;left:12px;right:12px}.location-pill,.weather-pill{height:25px;font-size:7px;padding:0 8px}.scene-caption{top:45px;left:14px;font-size:8px}.scene-hint{top:55px;right:13px;font-size:8px;max-width:120px;text-align:right}.scene-people{padding:0 5% 48%;gap:0}.character-figure{height:min(35%,250px);min-width:95px;max-width:38%}.scene-action{bottom:42%;right:11px;padding:7px 9px;font-size:7px}.dialogue-card{left:10px;right:10px;bottom:10px;min-height:0;padding:12px 12px 8px}.speaker-icon{width:26px;height:26px}.speaker-meta b{font-size:8px}.dialogue-text{font-size:13px;margin:8px 0}.choice-list{grid-template-columns:1fr;gap:5px}.choice-button{min-height:34px;padding:6px 8px}.dialogue-footer{margin-top:8px}.dialogue-footer>span{max-width:65%;font-size:7px}.bottom-bar{height:27px}.quote{font-size:9px}.controls-legend{display:none}.right-rail{order:3;display:block;padding-top:10px}.right-heading{height:22px}.people-list{display:flex;overflow:auto;gap:7px;margin-top:5px;padding-bottom:4px}.person-card{min-width:170px;padding:7px;grid-template-columns:36px 1fr 12px;gap:7px}.person-portrait{height:37px;width:36px}.rail-divider{display:block;margin:11px 0}.town-heading{height:22px}.town-note{margin-top:6px;padding:9px}.town-note p{font-size:11px;margin-bottom:6px}.memory-card{display:inline-grid;width:calc(65% - 5px);margin-top:8px}.save-status{display:inline-flex;margin:0 0 0 10px}.modal-card{padding:27px 22px 22px}.modal-card h2{font-size:25px}}
@media(max-height:700px) and (min-width:701px){.game-layout{padding-top:13px}.scene-card{height:calc(100vh - 105px);min-height:560px}.dialogue-card{bottom:12px}.scene-action{bottom:235px}}

(() => {
  'use strict';
  const SAVE_KEY = 'aoshima-summer-save-v1';
  const DAYS = ['MON','TUE','WED','THU','FRI','SAT','SUN'];
  const LOCATIONS = [
    {id:'square',name:'Town Square',icon:'⌂',time:'ANYTIME',mood:'The town is waking slowly',sky:['#a8c9c8','#f4c995','#738e86'],kind:'square',people:['nami']},
    {id:'harbor',name:'Blueglass Harbor',icon:'≈',time:'AFTERNOON',mood:'Salt air and gulls overhead',sky:['#80b7c4','#f2c99d','#3e8793'],kind:'harbor',people:['nami','ren']},
    {id:'cafe',name:'Sora Café',icon:'☕',time:'MIDDAY',mood:'Something sweet in the oven',sky:['#d6b99b','#f4dbb1','#988c78'],kind:'cafe',people:['ren']},
    {id:'garden',name:'Hillside Garden',icon:'❀',time:'MORNING',mood:'Dew still clings to the leaves',sky:['#97b99d','#dfd1a6','#738870'],kind:'garden',people:['mika']},
    {id:'station',name:'Old Station',icon:'▤',time:'EVENING',mood:'A train sighs in the distance',sky:['#8e9ba8','#edb78f','#70777d'],kind:'station',people:['mika','ren']}
  ];
  const PEOPLE = {
    nami:{id:'nami',name:'Nami Kuroda',age:22,role:'Illustrator · harbor regular',short:'Sketches the changing sky',color:'#db826e',hair:'#44314a',skin:'#f3c9b0',eye:'#638995',icon:'✎',spot:'harbor',bio:'A freelance illustrator who came home to paint the sea. Nami is 22, thoughtful, and happiest with a sketchbook in hand. She likes honesty more than grand gestures.'},
    ren:{id:'ren',name:'Ren Hayashi',age:23,role:'Café apprentice · 23',short:'Perfecting his lemon tart',color:'#5d9c9b',hair:'#344956',skin:'#e6b89a',eye:'#4b827c',icon:'☕',spot:'cafe',bio:'Twenty-three and learning to run his aunt’s little café, Ren jokes when he is nervous and remembers everyone’s order. He appreciates patience and a good pun.'},
    mika:{id:'mika',name:'Mika Fujita',age:21,role:'Botany student · 21',short:'Growing flowers for the festival',color:'#8a9c6c',hair:'#49394a',skin:'#f0c8b3',eye:'#668d75',icon:'❀',spot:'garden',bio:'A 21-year-old botany student spending the summer with her grandparents. Mika is quietly funny, observant, and always has a cutting or seed packet in her pocket.'}
  };
  const QUOTES=['“The sea keeps all the little things we almost said.”','“A familiar road can still lead somewhere new.”','“Good things grow at their own pace.”','“Some afternoons are made for doing nothing.”','“Even the smallest light changes the harbor.”','“The best plans leave a little room for surprise.”','“Summer is a collection of borrowed golden hours.”'];
  const $ = id => document.getElementById(id);
  const freshState = () => ({day:1,energy:3,location:'square',bonds:{nami:0,ren:0,mika:0},festival:0,flags:{},memories:[],journal:[],name:'Yuki Tanaka',intro:true,ended:false,sound:false});
  let state = loadState();
  function loadState(){try{const saved=JSON.parse(localStorage.getItem(SAVE_KEY)||'null');return saved?{...freshState(),...saved,bonds:{...freshState().bonds,...saved.bonds},flags:{...saved.flags}}:freshState()}catch{return freshState()}}
  function save(show=false){localStorage.setItem(SAVE_KEY,JSON.stringify(state));$('saveStatus').innerHTML='<span class="status-dot"></span> YOUR SUMMER IS SAVED';if(show)toast('Your summer is tucked away safely.');}
  function toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2300)}
  function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
  function personSvg(person,full=false){
    const p=typeof person==='string'?PEOPLE[person]:person, h=full?400:130, w=full?180:100;
    if(!p)return '';
