import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime=join(process.env.HOME,'.local/share/omgithub-playwright');
const require=createRequire(join(runtime,'package.json'));
const {chromium}=require('playwright');
const config=JSON.parse(readFileSync(join(runtime,'linux.json'),'utf8'));
const browser=await chromium.launch({...config.browser.launchOptions,headless:true});
const context=await browser.newContext({viewport:{width:1280,height:900}});
const page=await context.newPage();
const errors=[];
page.on('pageerror',e=>errors.push(e.message));
const response=await page.goto('http://127.0.0.1:3000',{waitUntil:'networkidle',timeout:30000});
if(!response?.ok()) throw new Error(`Preview returned ${response?.status()}`);
await page.locator('.choice-button').filter({hasText:'Take the scenic road into town'}).click();
for(const [location,task] of [['harbor','Help hang lanterns along the pier'],['cafe','Help Ren prepare festival treats'],['garden','Gather flowers for the festival stalls']]){
  await page.locator(`[data-location="${location}"]`).click();
  await page.locator('#sceneAction').click();
  await page.locator('.choice-button').filter({hasText:task}).click();
}
if(!(await page.locator('#festivalCaption').innerText()).startsWith('All set')) throw new Error('Festival did not complete all preparations');
await page.locator('#continueButton').click();
for(let day=2;day<=6;day++){
  const label=await page.locator('#dayLabel').innerText();
  if(!label.includes(String(day).padStart(2,'0'))) throw new Error(`Expected day ${day}, got ${label}`);
  for(let n=0;n<3;n++){
    await page.locator('#sceneAction').click();
    const quiet=page.locator('.choice-button').filter({hasText:'Take a quiet moment and enjoy the view'});
    if(await quiet.count()) await quiet.click();
    else await page.locator('.choice-button').filter({hasText:'Watch the last train roll by'}).click();
  }
  if(day<6) await page.locator('#continueButton').click();
}
if(!(await page.locator('#speakerName').innerText()).includes('THE SUMMER FESTIVAL')) throw new Error('Festival scene did not trigger on day 6');
await page.locator('.choice-button').filter({hasText:'Join everyone beneath the lanterns'}).click();
if(!(await page.locator('#memoryCount').innerText()).includes('4')) throw new Error('Festival memory/save update missing');
await page.getByRole('button',{name:'Save game'}).click();
await page.reload({waitUntil:'networkidle'});
if(!(await page.locator('#dayLabel').innerText()).includes('06')) throw new Error('Save did not persist across reload');
if(errors.length) throw new Error(`Browser errors: ${errors.join('; ')}`);
mkdirSync('/tmp/opencode',{recursive:true});
await page.screenshot({path:'/tmp/opencode/aoshima-latest.jpg',type:'jpeg',quality:72});
console.log(JSON.stringify({status:response.status(),day:await page.locator('#dayLabel').innerText(),festival:await page.locator('#festivalCaption').innerText(),memories:await page.locator('#memoryCount').innerText(),pageErrors:errors,screenshot:'/tmp/opencode/aoshima-latest.jpg'}));
await browser.close();
