if(!(await page.locator('#dayLabel').innerText()).includes('06')) throw new Error('Save did not persist across reload');
if(errors.length) throw new Error(`Browser errors: ${errors.join('; ')}`);
mkdirSync('/tmp/opencode',{recursive:true});
await page.screenshot({path:'/tmp/opencode/aoshima-latest.jpg',type:'jpeg',quality:72});
console.log(JSON.stringify({status:response.status(),day:await page.locator('#dayLabel').innerText(),festival:await page.locator('#festivalCaption').innerText(),memories:await page.locator('#memoryCount').innerText(),pageErrors:errors,screenshot:'/tmp/opencode/aoshima-latest.jpg'}));
await browser.close();
