import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime=join(process.env.HOME,'.local/share/omgithub-playwright');
const require=createRequire(join(runtime,'package.json'));
const {chromium}=require('playwright');
const config=JSON.parse(readFileSync(join(runtime,'linux.json'),'utf8'));
const browser=await chromium.launch({...config.browser.launchOptions,headless:true});
const page=await browser.newPage({viewport:{width:390,height:844}});
const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.goto('http://127.0.0.1:3000',{waitUntil:'networkidle'});
const metrics=await page.evaluate(()=>({viewport:innerWidth,documentWidth:document.documentElement.scrollWidth,bodyWidth:document.body.scrollWidth,layout:getComputedStyle(document.querySelector('.game-layout')).gridTemplateColumns}));
if(metrics.documentWidth>metrics.viewport||metrics.bodyWidth>metrics.viewport)throw new Error(`Mobile horizontal overflow: ${JSON.stringify(metrics)}`);
if(errors.length)throw new Error(errors.join('; '));
console.log(JSON.stringify({mobile:metrics,pageErrors:errors}));
await browser.close();
